camera.position.set(0, 1.4, 5);
scene.background = new THREE.Color('#fafafa');
scene.add(new THREE.AmbientLight(0xffffff, 0.7));
var dl = new THREE.DirectionalLight(0xffffff, 0.9); dl.position.set(3, 5, 4); scene.add(dl);
for (var i = 0; i < 6; i++) {
  var a = i * Math.PI / 3;
  var c = new THREE.Mesh(new THREE.SphereGeometry(0.3, 24, 24), new THREE.MeshStandardMaterial({ color: '#374151' }));
  c.position.set(Math.cos(a) * 1.3, Math.sin(a) * 1.3, 0); group.add(c);
  var h = new THREE.Mesh(new THREE.SphereGeometry(0.18, 20, 20), new THREE.MeshStandardMaterial({ color: '#bfdbfe' }));
  h.position.set(Math.cos(a) * 2.2, Math.sin(a) * 2.2, 0); group.add(h);
  var b2 = i + 1;
  var a2 = b2 * Math.PI / 3;
  var p1 = new THREE.Vector3(Math.cos(a) * 1.3, Math.sin(a) * 1.3, 0);
  var p2 = new THREE.Vector3(Math.cos(a2) * 1.3, Math.sin(a2) * 1.3, 0);
  var d = p2.clone().sub(p1);
  var bond = new THREE.Mesh(new THREE.CylinderGeometry(i % 2 ? 0.05 : 0.09, i % 2 ? 0.05 : 0.09, d.length(), 12), new THREE.MeshStandardMaterial({ color: '#6b7280' }));
  bond.position.copy(p1.clone().add(p2).multiplyScalar(0.5));
  bond.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.normalize());
  group.add(bond);
}
var cloud = new THREE.Mesh(new THREE.TorusGeometry(1.3, 0.22, 16, 64), new THREE.MeshStandardMaterial({ color: '#7c3aed', transparent: true, opacity: 0.18 }));
group.add(cloud);
return { update: function (t) { group.rotation.y = t * 0.4; group.rotation.x = 0.6 + Math.sin(t * 0.4) * 0.15; } };
